def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(r.count(c) for r in grid))
    # Extend diagonal runs of non-background colors, in their established direction.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, -1), (1, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    er, ec = rr + dr, cc + dc
                    while 0 <= er < h and 0 <= ec < w and grid[er][ec] == bg:
                        out[er][ec] = color
                        er += dr; ec += dc
    return out
